CREATE TABLE IF NOT EXISTS stations (icao TEXT PRIMARY KEY, city TEXT NOT NULL, region TEXT NOT NULL DEFAULT '', cp_name TEXT NOT NULL DEFAULT '', cp_freq TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS entries (id TEXT PRIMARY KEY, loc TEXT NOT NULL REFERENCES stations(icao), cat TEXT NOT NULL CHECK (cat IN ('eat','drink','hotel','act')), name TEXT NOT NULL, area TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, up INTEGER NOT NULL DEFAULT 0, down INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_entries_loc ON entries(loc);
